def hold_value(weights, values, cap, k):
    order = sorted(range(len(weights)), key=lambda i: values[i] / weights[i], reverse=True)
    total = used = load = 0
    for i in order:
        if used < k and load + weights[i] <= cap:
            load += weights[i]
            total += values[i]
            used += 1
    return total

def hold_value(weights, values, cap, k):
    k = min(k, len(weights))
    best = [[0] * (cap + 1) for _ in range(k + 1)]
    for w, v in zip(weights, values):
        for c in range(1, k + 1):
            row, fewer = best[c], best[c - 1]
            for t in range(cap, w - 1, -1):
                if fewer[t - w] + v > row[t]:
                    row[t] = fewer[t - w] + v
    return best[k][cap]
